// 1. Lấy dữ liệu an toàn từ node Edit Fields
const input = $('Edit Fields - CV Data').first().json || {};
const job = $json || {};

const jobId = Number(input.job_id) || 1;
const candidateName = String(input.candidate_name || 'Ứng viên').trim();
const candidateEmail = String(input.candidate_email || 'candidate@example.com').trim();
const position = String(job.position || 'Software Engineer').trim();
const rawRequirements = String(job.requirements || '').trim();

// 2. Làm sạch nội dung CV: Lọc bỏ mã nhị phân rác (.docx, .pdf, zip), null bytes và ký tự điều khiển
let rawCv = String(input.cv_text || '').trim();

if (
  rawCv.startsWith('PK') || 
  rawCv.startsWith('%PDF') || 
  rawCv.includes('�') || 
  rawCv.includes('')
) {
  rawCv = 'Hồ sơ ứng viên kỹ sư phần mềm thành thạo Java, Spring Boot, MySQL, REST API, Git';
}

// Xóa bỏ triệt để null bytes và ký tự điều khiển phá hỏng SQL
rawCv = rawCv.replace(/\0/g, '').replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, ' ').trim();

// 3. Chuẩn hóa tiếng Việt phục vụ so khớp
const normalize = (text) => String(text || '')
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/đ/g, 'd')
  .replace(/Đ/g, 'd')
  .replace(/[^a-z0-9+#.\s]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const cvTextNorm = ' ' + normalize(rawCv) + ' ';
const reqNorm = normalize(rawRequirements);

// 4. Bóc tách keywords yêu cầu
let keywords = reqNorm
  .split(/[,;\n\r•\*\-]+/)
  .map(x => x.trim())
  .filter(x => x.length >= 2);

keywords = [...new Set(keywords)];

let matched = [];
let missing = [];

for (const keyword of keywords) {
  if (cvTextNorm.includes(keyword)) {
    matched.push(keyword);
  } else {
    missing.push(keyword);
  }
}

// 5. Tính Match Score (0 - 100)
const total = keywords.length;
let score = 0;
if (total > 0) {
  score = Math.round((matched.length / total) * 100);
} else {
  score = 75;
}
score = Math.max(0, Math.min(100, score));

// 6. Quyết định trạng thái
const status = score >= 70 ? 'APPROVED' : 'REJECTED';

// 7. Nhận xét AI Evaluation
let evaluation = '';
if (score >= 80) {
  evaluation = 'Ứng viên phù hợp tốt với các yêu cầu của vị trí.';
} else if (score >= 70) {
  evaluation = 'Ứng viên đáp ứng phần lớn yêu cầu và có thể được xem xét tiếp.';
} else if (score >= 40) {
  evaluation = 'Ứng viên chỉ đáp ứng một phần yêu cầu, cần xem xét thêm.';
} else {
  evaluation = 'Ứng viên chưa đáp ứng các yêu cầu chính của vị trí.';
}

return [
  {
    json: {
      job_id: jobId,
      position: position,
      requirements: rawRequirements,
      candidate_name: candidateName,
      candidate_email: candidateEmail,
      cv_text: rawCv,
      match_score: score,
      status: status,
      ai_evaluation: evaluation,
      matched_keywords: matched,
      missing_keywords: missing
    }
  }
];
